&reftitle.description;
public Yaf_DispatchernullfalseYaf_Dispatcher::registerPlugin Yaf_Plugin_Abstractplugin
Registra un plugin (véase Yaf_Plugin_Abstract). Generalmente se registran plugins en el Arranque (véase la clase Yaf_Bootstrap_Abstract).

  &reftitle.examples;

   Ejemplo de Yaf_Dispatcher::registerPlugin


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract {
  public function _initPlugin(Yaf_Dispatcher $dispatcher) {
    /**
    * Yaf asume que los scripts de plugins están en [application.directory] . "/plugins"
    * en este caso, será:
    * [application.directory] . "/plugins/" . "User" . [application.ext]
    */
    $user = new UserPlugin();
    $dispatcher->registerPlugin($user);
  }
}
?>
